41	  public readonly classList = {
42	    add: (...names: string[]): void => {
43	      const existing = this.x_ClassNames();
44	      for (const name of names) {
45	        if (!existing.includes(name)) {
46	          existing.push(name);
47	        }
48	      }
49	      this.className = existing.join(" ");
50	    },
51	    remove: (...names: string[]): void => {
52	      this.className = this.x_ClassNames()
53	        .filter((name) => !names.includes(name))
54	        .join(" ");
55	    },
56	    contains: (name: string): boolean => this.x_ClassNames().includes(name),
57	    toggle: (name: string, force?: boolean): boolean => {
58	      const shouldAdd = force == null ? !this.classList.contains(name) : force;
59	      if (shouldAdd) {
60	        this.classList.add(name);
61	      } else {
62	        this.classList.remove(name);
63	      }
64	      return shouldAdd;
65	    },
66	  };
