113	  public appendChild(child: FakeElement): FakeElement
114	  {
115	    if (child.parentNode) {
116	      child.parentNode.removeChild(child);
117	    }
118	    child.parentNode = this;
119	    this.children.push(child);
120	
121	    if (this.tagName === "SELECT" && child.tagName === "OPTION") {
122	      if (child.selected || this.value === "") {
123	        this.value = child.value;
124	      }
125	    }
126	
127	    if (this.classList.contains("agui-chat-transcript")) {
128	      this.scrollHeight = Math.max(this.scrollHeight, this.children.length * 500);
