144	  public addEventListener(type: string, handler: Listener): void
145	  {
146	    this.x_listeners[type] = this.x_listeners[type] || [];
147	    this.x_listeners[type].push(handler);
148	  }
149	
150	  public removeEventListener(type: string, handler?: Listener): void
151	  {
152	    if (!handler) {
153	      delete this.x_listeners[type];
154	      return;
155	    }
156	    this.x_listeners[type] = (this.x_listeners[type] || []).filter(
157	      (entry) => entry !== handler,
158	    );
159	  }
160	
161	  public dispatchEvent(event: Record<string, unknown>): boolean
162	  {
163	    const type = String(event.type || "");
164	    for (const handler of this.x_listeners[type] || []) {
165	      handler(event);
166	    }
167	    return true;
168	  }
169	
170	  public click(): void
171	  {
172	    this.dispatchEvent({ type: "click" });
173	  }
174	
175	  public querySelector(selector: string): FakeElement | null
176	  {
177	    return this.querySelectorAll(selector)[0] || null;
178	  }
179	
180	  public querySelectorAll(selector: string): FakeElement[]
181	  {
182	    const results: FakeElement[] = [];
183	    const matcher = this.x_CreateMatcher(selector);
184	    const stack = [...this.children];
185	    while (stack.length > 0) {
186	      const node = stack.shift();
187	      if (!node) {
188	        continue;
189	      }
190	      if (matcher(node)) {
191	        results.push(node);
192	      }
193	      stack.push(...node.children);
194	    }
195	    return results;
196	  }
197	
198	  private x_ClassNames(): string[]
199	  {
200	    return this.className.split(/\s+/).filter(Boolean);
201	  }
202	
203	  private x_CreateMatcher(selector: string): (node: FakeElement) => boolean
204	  {
205	    if (selector.startsWith(".")) {
206	      const className = selector.slice(1);
207	      return (node: FakeElement) => node.x_ClassNames().includes(className);
208	    }
209	    const tagName = selector.toUpperCase();
210	    return (node: FakeElement) => node.tagName === tagName;
211	  }
212	}
