317	function LoadChatHarness(options?: { touch?: boolean }): ChatHarness
318	{
319	  const document = new FakeDocument();
320	  const pendingFrames: Array<(() => void) | null> = [];
321	  const pendingTimers: Array<(() => void) | null> = [];
322	  const windowListeners: Record<string, Listener[]> = {};
323	  let idCounter = 0;
324	
325	  FakeWebSocket.instances = [];
326	
327	  const context: Record<string, any> = {
328	    console,
329	    URLSearchParams,
330	    WebSocket: FakeWebSocket,
331	    document,
332	    location: {
333	      hash: "#/piles/default/sessions/sess-1",
334	      protocol: "http:",
335	      host: "127.0.0.1:9004",
336	    },
337	    localStorage: {
338	      getItem: () => null,
339	      setItem: () => undefined,
340	    },
341	    crypto: {
342	      randomUUID: () => {
343	        idCounter += 1;
344	        return "test-id-" + idCounter;
345	      },
346	    },
347	    matchMedia: () => ({ matches: options?.touch === true }),
348	    requestAnimationFrame: (callback: () => void): number => {
349	      pendingFrames.push(callback);
350	      return pendingFrames.length;
351	    },
352	    cancelAnimationFrame: (id: number): void => {
353	      pendingFrames[id - 1] = null;
354	    },
355	    setTimeout: (callback: () => void): number => {
356	      pendingTimers.push(callback);
357	      return pendingTimers.length;
358	    },
359	    clearTimeout: (id: number): void => {
360	      pendingTimers[id - 1] = null;
361	    },
362	    addEventListener: (type: string, handler: Listener): void => {
363	      windowListeners[type] = windowListeners[type] || [];
364	      windowListeners[type].push(handler);
365	    },
366	    removeEventListener: (type: string, handler: Listener): void => {
367	      windowListeners[type] = (windowListeners[type] || []).filter(
368	        (entry) => entry !== handler,
369	      );
370	    },
371	  };
372	  context.window = context;
373	  context.globalThis = context;
374	  if (options?.touch === true) {
375	    context.ontouchstart = null;
376	  }
377	
378	  vm.createContext(context);
379	  vm.runInContext(fs.readFileSync(x_aguiChatJsPath, "utf8"), context);
380	
381	  const handles: any[] = [];
382	  const originalCreate = context.ChatView.create;
383	  context.ChatView.create = function (...args: unknown[]): unknown {
384	    const handle = originalCreate.apply(context.ChatView, args);
385	    handles.push(handle);
386	    return handle;
387	  };
388	
389	  vm.runInContext(fs.readFileSync(x_sheafChatJsPath, "utf8"), context);
390	
391	  return {
392	    app: document.app,
393	    sockets: FakeWebSocket.instances,
394	    handles,
395	    flushAnimationFrames: () => {
396	      while (pendingFrames.length > 0) {
397	        const callback = pendingFrames.shift();
398	        if (callback) {
399	          callback();
400	        }
401	      }
402	    },
403	    runTimers: () => {
404	      while (pendingTimers.length > 0) {
405	        const callback = pendingTimers.shift();
406	        if (callback) {
407	          callback();
408	        }
409	      }
410	    },
411	  };
412	}
