414	function Frames(socket: FakeWebSocket, kind?: string): Array<Record<string, any>>
415	{
416	  const frames = socket.sent.map((data) => JSON.parse(data) as Record<string, any>);
417	  return kind ? frames.filter((frame) => frame.kind === kind) : frames;
418	}
