420	function LastFrame(socket: FakeWebSocket, kind: string): Record<string, any>
421	{
422	  const frames = Frames(socket, kind);
423	  assert.ok(frames.length > 0, "expected at least one " + kind + " frame");
424	  return frames[frames.length - 1];
425	}
