427	function ServerEnvelope(
428	  kind: string,
429	  payload: unknown,
430	  sequence?: number,
431	): Record<string, unknown>
432	{
433	  const envelope: Record<string, unknown> = {
434	    v: 1,
435	    id: "server-" + kind + "-" + String(sequence || "unsequenced"),
436	    kind,
437	    pile: "default",
438	    sessionId: "sess-1",
439	    timestamp: "2026-06-08T00:00:00.000Z",
440	    payload,
441	  };
442	  if (sequence != null) {
443	    envelope.sequence = sequence;
444	  }
445	  return envelope;
446	}
