491	  socket.receive(
492	    ServerEnvelope("chat.user_message", {
493	      messageId,
494	      text: "Hello from user",
495	    }, 1),
496	  );
497	  socket.receive(
498	    ServerEnvelope("agui.event", {
499	      type: "TEXT_MESSAGE_START",
500	      messageId,
501	      role: "user",
502	    }, 2),
503	  );
504	  socket.receive(
505	    ServerEnvelope("agui.event", {
506	      type: "TEXT_MESSAGE_CONTENT",
507	      messageId,
508	      delta: "Hello from user",
509	    }, 3),
510	  );
511	  socket.receive(
512	    ServerEnvelope("agui.event", {
513	      type: "TEXT_MESSAGE_END",
